static void ui_merchant_utility(const Combat*g,int choice){unsigned id=g->utilityMenu;ui_panel(100,92,440,310,id==62?"Item Appraisal":id==65?"Change Cart":"Cart management",1,-1);ui_scaled(112,114,.85f,"Bag %lld/%d | Cart %lld/8000",(long long)(inventory_weight(g)/10),inventory_weight_max(g)/10,(long long)(inventory_cart_weight(g)/10));
 int count=skill_utility_rows(g),start=choice/8*8;for(int k=start;k<count&&k<start+8;k++){int y=141+(k-start)*25;ui_cell(110,y-2,420,23,k==choice);if(id==62){const OwnedItem52*p=inventory_unidentified52(g,k);const OwnedRule52*r=p?item_rule52(p->sourceID):NULL;ui_scaled(118,y,.9f,"Identify %s #%d - %d SP",r&&r->kind==OWNED_WEAPON52?"weapon":"armour",k+1,g->utilityItemRank52?0:10);}else if(id==65){static const int levels[5]={1,41,66,81,91};ui_scaled(118,y,.9f,"Style %d: requires level %d - 40 SP",k+1,levels[k]);}else if(!g->cartOwned)ui_scaled(118,y,.9f,"Rent a cart at the Prontera merchant");else{int item=k%ITEM_COUNT,take=k>=ITEM_COUNT;ui_scaled(118,y,.85f,"%s %.20s: %d",take?"Take":"Store",itemDefs[item].name,take?inventory_box_count52(g,1,item):inventory_count(g,item));}}
 if(id==63)ui_hint64(112,354,.8f,"L/R: quantity %d | Up/down | A: transfer | B: close",g->cartQuantity?g->cartQuantity:1);else ui_hint64(112,354,.8f,"Up/down: choose | A: confirm | B: close");ui_scaled(112,377,.7f,"%.85s",g->log);}
static void ui_utility(const Combat*g,int choice){if(g->utilityMenu==503){ui_companions191(g,choice);return;}if(g->utilityMenu==502){ui_mercenary180(g,choice);return;}if(g->utilityMenu==700||g->utilityMenu==SK52_WS_WEAPONREFINE){int card=g->utilityMenu==700;ui_panel(100,76,440,336,card?"Insert card":"Upgrade weapon",1,-1);int n=inventory_action_rows52(g),start=choice/8*8;for(int i=start;i<n&&i<start+8;i++){const OwnedItem52*p=inventory_action_row52(g,i);int id=inventory_catalog52(p->sourceID),yy=111+(i-start)*25;ui_cell(110,yy-2,420,23,choice==i);ui_scaled(120,yy,.85f,"+%u %.32s [%u/%u]",p->refine,itemDefs[id].name,(p->cards[0]!=0)+(p->cards[1]!=0)+(p->cards[2]!=0)+(p->cards[3]!=0),item_rule52(p->sourceID)->slots);}ui_hint64(112,345,.8f,card?"A: insert permanently   B: cancel":"A: attempt upgrade   B: cancel");ui_scaled(112,365,.75f,card?"Unequip gear first. Inserted cards stay with this item.":"Requires ore. Failed refinement destroys the weapon.");ui_scaled(112,389,.7f,"%.80s",g->log);return;}if(g->utilityMenu==500||g->utilityMenu==501){ui_companion50(g,choice);return;}if(g->utilityMenu==600||g->utilityMenu==239){ui_craft50(g,choice);return;}if(g->utilityMenu==107||g->utilityMenu==95){int autoSpell=g->utilityMenu==95;ui_panel(100,76,440,336,autoSpell?"Hindsight - select learned spell":"Create Elemental Converter",1,-1);int n=skill_utility_rows(g);for(int i=0;i<n;i++){int yy=110+i*30;ui_cell(110,yy-2,420,27,choice==i);if(autoSpell)ui_text(120,yy,"%s",skillDefs[class_auto_choice48(g,i)].name);else {static const char*names[]={"Fire: 3 Red Bat Wings","Water: 3 Snail Shells","Earth: 3 Horns","Wind: 3 Scorpion Tails"};ui_text(120,yy,"%s",names[i]);}}ui_hint64(112,345,.85f,autoSpell?"A: select   B: cancel":"Each recipe: 1 Blank Scroll + 30 SP");ui_scaled(112,375,.8f,"%.75s",g->log);return;}if(g->utilityMenu==62||g->utilityMenu==63||g->utilityMenu==65){ui_merchant_utility(g,choice);return;}if(g->utilityMenu==60){ui_panel(115,92,410,200,"Arrow Crafting",1,-1);for(int i=0;i<2;i++){ui_cell(127,124+i*35,386,29,i==choice);ui_text(139,130+i*35,"%s  x %d  ->  %d Arrows",i?"Tree Root":"Jellopy",inventory_count(g,i?ITEM_TREE_ROOT:ITEM_JELLOPY),i?7:4);}ui_text(129,215,"A: craft once (10 SP)  B: cancel");ui_scaled(129,248,.8f,"%.70s",g->log);return;}int teleport=g->utilityMenu==52;ui_panel(115,92,410,268,teleport?"Teleport":"Warp Portal destination",1,-1);int n=skill_utility_rows(g);for(int i=0;i<n;i++){ui_cell(127,124+i*35,386,29,i==choice);if(teleport){if(i)ui_text(139,130+i*35,"Return home: %s",mapLabels[g->home.map]);else ui_text(139,130+i*35,"Random safe location on this map");}else{WorldPosition p=i?g->memos[i-1]:g->home;ui_text(139,130+i*35,"%s: %s",i?"Memo":"Home",mapLabels[p.map]);}}ui_hint64(129,278,.85f,"A: confirm   B: cancel without cost");ui_hint64(129,299,.8f,"%s",teleport?"Rank2 unlocks home; random stays on this map.":"Y: remember this map with learned Warp Portal.");ui_scaled(129,324,.75f,"%.70s",g->log);}
